import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { ScatterChart } from "@/registry/erbium/charts/scatter-chart";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



const meta = {
  component: ScatterChart,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Pass one row per point and name the numeric fields with `x` and `y`. `group` colors points by a category, and the legend hides and shows each group.

```tsx
import { ScatterChart } from "@/registry/erbium/charts/scatter-chart";

<ScatterChart
  ariaLabel="Price against rating"
  data={products}
  x="price"
  y="rating"
  group="category"
/>;
```

Name both axes with `xLabel` and `yLabel`. `format` formats y values and `xFormat` formats x values.",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof ScatterChart>;

export default { ...meta, title: "Charts/Scatter Chart",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

export const Playground: StoryObj<{
  grid: boolean;
  legend: boolean;
  radius: number;
  tooltip: boolean;
}> = {
  argTypes: {
    grid: { control: "boolean" },
    legend: { control: "boolean" },
    radius: { control: { max: 10, min: 2, type: "number" } },
    tooltip: { control: "boolean" },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { chartNumberFormat } from "@/registry/erbium/charts/chart";
import { ScatterChart } from "@/registry/erbium/charts/scatter-chart";
import { products } from "../examples/data";

const priceFormat = chartNumberFormat(
  { currency: "USD", maximumFractionDigits: 0, style: "currency" },
  "en",
);

const ratingFormat = chartNumberFormat({ maximumFractionDigits: 1 }, "en");

export const defaultProps = {
  grid: true,
  legend: true,
  radius: 4,
  tooltip: true,
} satisfies { grid: boolean; legend: boolean; radius: number; tooltip: boolean };

export default function ScatterChartPlaygroundExample(
  args: { grid: boolean; legend: boolean; radius: number; tooltip: boolean } = defaultProps,
) {
  return (
    <div className="w-full p-4">
      <ScatterChart
        ariaLabel="Product price against average rating"
        data={products}
        x="price"
        y="rating"
        group="category"
        xLabel="Price"
        yLabel="Rating"
        xFormat={priceFormat}
        format={ratingFormat}
        initialWidth={640}
        {...args}
      />
    </div>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

import { chartNumberFormat } from "@/registry/erbium/charts/chart";
import { ScatterChart } from "@/registry/erbium/charts/scatter-chart";
import { products } from "../examples/data";

const priceFormat = chartNumberFormat(
  { currency: "USD", maximumFractionDigits: 0, style: "currency" },
  "en",
);

const ratingFormat = chartNumberFormat({ maximumFractionDigits: 1 }, "en");

export const defaultProps = {
  grid: true,
  legend: true,
  radius: 4,
  tooltip: true,
} satisfies { grid: boolean; legend: boolean; radius: number; tooltip: boolean };

export default function ScatterChartPlaygroundExample(
  args: { grid: boolean; legend: boolean; radius: number; tooltip: boolean } = defaultProps,
) {
  return (
    <div className="w-full p-4">
      <ScatterChart
        ariaLabel="Product price against average rating"
        data={products}
        x="price"
        y="rating"
        group="category"
        xLabel="Price"
        yLabel="Rating"
        xFormat={priceFormat}
        format={ratingFormat}
        initialWidth={640}
        {...args}
      />
    </div>
  );
}
